using Microsoft.AspNetCore.Antiforgery;
using Microsoft.AspNetCore.Authentication;
using SalekhPos.Integrations.Application;
using SalekhPos.Integrations.Contracts;
namespace SalekhPos.Api.Authentication; public static class WebIntegrationEndpoints { public static void MapWebIntegrationEndpoints(this WebApplication app) { var g = app.MapGroup("/bff/api/v1").AllowAnonymous().RequireRateLimiting("business"); g.MapGet("/organizations/{organizationId:guid}/integrations/connections", Connections); g.MapPost("/organizations/{organizationId:guid}/integrations/connections", Create); g.MapPost("/organizations/{organizationId:guid}/integrations/connections/{connectionId:guid}/disable", Disable); g.MapGet("/organizations/{organizationId:guid}/integrations/webhooks", Webhooks); g.MapPost("/organizations/{organizationId:guid}/integrations/webhooks/{deliveryId:guid}/retry", RetryDeadLetter); } private static async Task<IResult> Connections(Guid organizationId, HttpContext c, WebAuthenticationState s, IIntegrationService svc, CancellationToken ct) { var i = await Id(c, s); return i is null ? Unauth(s) : Results.Ok(await svc.ListConnectionsAsync(i, organizationId, Page(c), null, ct)); } private static async Task<IResult> Webhooks(Guid organizationId, HttpContext c, WebAuthenticationState s, IIntegrationService svc, CancellationToken ct) { var i = await Id(c, s); return i is null ? Unauth(s) : Results.Ok(await svc.ListDeliveriesAsync(i, organizationId, Page(c), null, ct)); } private static async Task<IResult> Create(Guid organizationId, CreateIntegrationConnectionRequest r, HttpContext c, WebAuthenticationState s, IAntiforgery a, IIntegrationService svc, CancellationToken ct) { var i = await Id(c, s); if (i is null) return Unauth(s); var op = await Op(c, s, a); if (op is null) return Invalid(); var x = await svc.CreateConnectionAsync(i, new(organizationId, Guid.NewGuid(), op.Value, r.Provider, r.DisplayName, r.Endpoint, r.SecretReference), ct); return x.Created ? Results.Created($"/bff/api/v1/organizations/{organizationId:D}/integrations/connections/{x.Value.Id:D}", x.Value) : Results.Ok(x.Value); } private static async Task<IResult> RetryDeadLetter(Guid organizationId, Guid deliveryId, RetryWebhookDeliveryRequest r, HttpContext c, WebAuthenticationState s, IAntiforgery a, IIntegrationService svc, CancellationToken ct) { var i = await Id(c, s); if (i is null) return Unauth(s); var op = await Op(c, s, a); if (op is null) return Invalid(); try { return Results.Ok(await svc.RetryDeadLetterAsync(i, organizationId, deliveryId, op.Value, r.Reason, ct)); } catch (ArgumentException) { return Invalid(); } } private static async Task<IResult> Disable(Guid organizationId, Guid connectionId, DisableIntegrationConnectionRequest r, HttpContext c, WebAuthenticationState s, IAntiforgery a, IIntegrationService svc, CancellationToken ct) { var i = await Id(c, s); if (i is null) return Unauth(s); var op = await Op(c, s, a); if (op is null) return Invalid(); return Results.Ok(await svc.DisableConnectionAsync(i, organizationId, connectionId, op.Value, r.Reason, ct)); } private static int Page(HttpContext c) => c.Request.Query.TryGetValue("pageSize", out var v) && int.TryParse(v, out var n) && n is >= 1 and <= 100 ? n : 100; private static async Task<Guid?> Op(HttpContext c, WebAuthenticationState s, IAntiforgery a) { if (!await WebAuthentication.ValidateMutation(c, a, s.Settings!) || !Guid.TryParseExact(c.Request.Headers["Idempotency-Key"], "D", out var id) || id == Guid.Empty) return null; return id; } private static async Task<IntegrationIdentity?> Id(HttpContext c, WebAuthenticationState s) { if (s.Settings is null) return null; var r = await c.AuthenticateAsync(WebAuthentication.CookieScheme); if (!r.Succeeded || r.Principal is null) return null; var iss = r.Principal.FindAll("iss").ToArray(); var sub = r.Principal.FindAll("sub").ToArray(); if (iss.Length != 1 || sub.Length != 1) return null; try { var i = new IntegrationIdentity(iss[0].Value, sub[0].Value); i.Validate(); return i; } catch (ArgumentException) { return null; } } private static IResult Unauth(WebAuthenticationState s) => s.Settings is null ? Results.Problem(statusCode: 503, title: "Web authentication is unavailable", extensions: new Dictionary<string, object?> { { "code", "web_authentication_unavailable" } }) : Results.Unauthorized(); private static IResult Invalid() => Results.Problem(statusCode: 400, title: "The integration request is invalid", extensions: new Dictionary<string, object?> { { "code", "invalid_integration_request" } }); }
